    time.current = performance.now(); pauseRef.current = pause; setPaused(pause);
    publish(next); saveSize(next.board.size); setDeal(n => n + 1); setCelebrate(false); setAnnouncement('');
    window.clearTimeout(announceTimer.current);
  };
